String utf = EncodingUtil.urlEncode('A B+Ω', 'UTF-8');
System.assertEquals('A+B%2B%CE%A9', utf);
System.assertEquals('A B+Ω', EncodingUtil.urlDecode(utf, 'utf8'));
String latin = EncodingUtil.urlEncode('café trail', 'ISO-8859-1');
System.assertEquals('caf%E9+trail', latin);
System.assertEquals('café trail', EncodingUtil.urlDecode(latin, 'latin1'));
System.assertEquals('café trail', EncodingUtil.urlDecode('caf%E9+trail', ' ISO_8859_1 '));

